INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b6a7676d-696e-5dc1-a2e3-10445334909f', '44df010c-1660-55c7-bd46-dea732e01d1c', 'en', $h$Anti Splashing Tape$h$, $h$anti-splashing-tape$h$, $h$Anti Splashing Tape – Sealing and Splash Prevention Tape$h$, $h$<div> <p><strong>Anti Splashing Tape</strong> is a high-performance sealing tape designed to prevent <em>liquid splashing</em>, <em>leakage</em> and <em>contamination</em> at pipe connections, joints and vibrating surfaces. It is used particularly in marine, industrial and maritime applications. Thanks to its durable structure, it provides long-lasting protection.</p><p>HD Marine Anti Splashing Tape is an <strong>easy-to-apply</strong> solution <strong>resistant to water, oil and chemical splashes</strong>, providing safe sealing at connection points requiring maintenance.</p> </div><div> <p>✔ <strong>Highly resistant sealing</strong> – Protects against water, oil and chemical splashes<br/>✔ <strong>Flexible and durable structure</strong> – Effective performance even under vibration<br/>✔ <strong>Easy application</strong> – Fast installation in tape form<br/><span>✔</span> <strong>Broad compatibility</strong> – On pipe connection elements and mounting surfaces<br/>✔ <strong>Long-lasting use</strong> – Resistant to wear and deformation</p> </div>$h$, $h$<div> <p>Anti Splashing Tape offers an effective sealing solution particularly in:</p><ul><li><strong>Pipe joints and connections</strong></li><li><strong>Surfaces subject to machine vibration</strong></li><li><strong>Marine engine rooms</strong></li><li><strong>Industrial facility lines</strong></li><li><strong>Splash and leak prevention in oil / fuel / water systems</strong></li></ul><p>and similar applications.</p> </div>$h$, $h$Anti Splashing Tape | HD Marine$h$, $h$Anti Splashing Tape is a high-performance sealing tape designed to prevent liquid splashing , leakage and contamination at pipe connections, joints and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5d40d304-ea80-54b8-bb8e-27bd101f8c45', '017c10f6-220d-5a7a-85f4-01dd686951f5', 'en', $h$What is Anti Splashing Tape?$h$, $h$<div> <p>Anti Splashing Tape is a highly resistant sealing tape used to prevent splashing and leakage at pipe connections.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fc03307c-6201-543f-b4c5-51a6173953dd', '43476fcd-d2d1-580c-a37e-f3e3a14bb6e3', 'en', $h$On which surfaces is it used?$h$, $h$<div> <p>It is used on pipe connections, assembly joints and vibrating surfaces.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c9c2be31-e3bc-5fd1-aba2-0d1fe563c4cc', 'c68b65e4-5714-5ad4-afdc-f92467e4ccee', 'en', $h$To which fluids is it resistant?$h$, $h$<div> <p>Thanks to its material structure resistant to water, oil and mild chemical splashes, it provides safe sealing.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('698d79bd-3ad7-53ad-a9fb-f5f7d20feb4e', '0840a7d6-e6ee-5208-8abd-8f89df366c6f', 'en', $h$Is it difficult to apply?$h$, $h$<div> <p>No, thanks to its tape form it is applied easily; no special tools are required.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('8319b30c-7d58-5f4f-8c1b-0debdddeb2af', '4ae6c6bb-a58e-5a16-866b-622cb26d9c6d', 'en', $h$Wilden® Compatible Spare Parts$h$, $h$wilden-compatible-spare-parts$h$, $h$Wilden® Compatible Spare Parts$h$, $h$<div> <div><p>WILDEN PUMP, one of the pioneering companies in its field, having developed the first compressed-air-operated diaphragm pumps in 1955, has held a leading position in the air-operated double diaphragm pump market from the very beginning. Since 1998, as part of the Dover Group, it has continued to rise, standing apart from its competitors in product variety and technology. HD Marine, since its founding, has worked with leading companies and manufacturers. It offers its customers suitable equipment and products in line with their needs, pump and spare part support, after-sales support, engineering services, and procurement and installation processes.</p></div> </div><div> <div><p>For Air-Operated Double Diaphragm Pumps, you can find many Wilden-brand-compatible spare parts you may need at HD Marine, such as diaphragms, seats, balls, pistons, gaskets, air valves, O-rings, hardware, clamp bands, mufflers and repair kits.</p><p>Wilden Type pump and spare part support is provided to the user in line with requirements and according to different places of use. One of the most important features of Wilden Type pumps is that they operate with energy-saving air distribution technology and, with a wide range of material options, are models that perform successfully in high-pressure applications without stalling or freezing.</p><p>Wilden Type pumps are divided into four main categories according to their areas of use: Metal-Bodied Air-Operated Double Diaphragm Pumps, Plastic-Bodied Air-Operated Double Diaphragm Pumps, Metal-Bodied High-Pressure Pumps, and Plastic Magnetically Coupled Centrifugal Pumps. Outside this group, Wilden Type pumps and spare parts used in different fields such as food applications and mining applications are also available.</p><p>The areas where Wilden Type pumps and spare parts are used generally include various applications such as alcohol, chemical treatment, acid / alkali / chemical, paint and pigment, drainage applications, petroleum-derived liquids, ceramic slip, glaze, and oil and solvent transfer.</p></div> </div>$h$, NULL, $h$Wilden® Compatible Spare Parts | HD Marine$h$, $h$WILDEN PUMP, one of the pioneering companies in its field, having developed the first compressed-air-operated diaphragm pumps in 1955, has held a leading…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('86fffe23-6ebe-5020-aadd-0998f9eee98b', 'a3abca29-00e2-5a6a-86ee-eb9f4c2cb152', 'en', $h$Aro® Compatible Spare Parts$h$, $h$aro-compatible-spare-parts$h$, $h$Aro® Compatible Spare Parts$h$, $h$<div> <div><p>Aro® first launched its air-operated double diaphragm pump product in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and is one of the leading AODD Pump brands.</p></div> </div><div> <div><p>ARO® air-operated diaphragm pumps have the capacity to handle a variety of viscous fluids and ensure non-stalling, ice-free operation. The unbalanced air valve design prevents the stalling problems associated with other pumps. Quick-dump exhaust valves direct cold exhaust air away from ice-prone components and prevent freezing. Depending on the type of liquid to be discharged, piston pump packages are available with multiple configurations for the pump section, including single-body, two-body or heavy-duty two-body designs.</p><p>ARO® diaphragm pumps, with their cost-effectiveness and reliable construction, are a good choice for industrial and chemical applications. The bolted, leak-free design eliminates cross-contamination and increases operator safety. The modular design, reduced part count and easy-to-use repair kits also minimize product repair time when needed.</p><p>HD Marine brings you reliable, quality products with spare parts compatible with double diaphragm (AODD) Pumps. HD Marine provides spare product support for many parts according to your preference, and is an address where you can find Aro spare parts such as <strong>valve balls, valve seats, diaphragms, gaskets, clamp bands, mufflers, pistons and valve rings</strong>.</p><p>In the event of any failure or maintenance need for Diaphragm Pumps, you can select Aro-brand-compatible products individually through the HD Marine site, or from the <strong>Aro Service Kits</strong> section you can access a service/repair kit containing screws, gaskets and many ring varieties together. Service kits come in two types: a wet kit for the wet side of your pneumatic double diaphragm pump, and a kit used for the maintenance and repair of the air side of your air-operated double diaphragm pump. Since these two kits contain different products, you should make your choice by considering which products you need and in which area you will use them.</p><p>Apart from <strong>Aro Service Kits</strong>, when you want to purchase products individually, you can also find <strong>Aro gaskets, Aro rings, Aro valve balls, Aro valve seats, Aro hardware and Aro diaphragms</strong>. However, it should be kept in mind that the area in which each industry uses its pumps, and the appropriate Aro spare part product for that area, will vary. According to your specific application needs such as chemical compatibility, temperature and sealing capacity, HD Marine offers its customers the most widely used and preferred quality materials and products in pump parts, such as <strong>Santoprene, Hytrel, N-fit, PTFE and Neoprene</strong>.</p></div> </div>$h$, NULL, $h$Aro® Compatible Spare Parts | HD Marine$h$, $h$Aro® first launched its air-operated double diaphragm pump product in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('ef8436d4-8d14-596c-ac47-9f22768be136', '160e4b7f-4479-5c48-a2da-27d2c4277745', 'en', $h$Sandpiper® Compatible Spare Parts$h$, $h$sandpiper-compatible-spare-parts$h$, $h$Sandpiper® Compatible Spare Parts$h$, $h$<div> <div><p>HD Marine delivers to its users the highest-quality spare parts compatible with the Sandpiper® brand. It has a complete, wide range of wear parts for Air-Operated Double Diaphragm Pumps, such as diaphragms, seats, balls, pistons, gaskets, air valves, O-rings, hardware, clamp bands, shafts, mufflers and repair kits.</p></div> </div><div> <div><p>The <strong>Sandpiper® air valve</strong> is one of the main elements of an Air-Operated Double Diaphragm pump. Sandpiper pumps use both internal air valve and external air valve designs and locations. The materials used in the air valve body can vary in quality, such as brass, aluminum, plastic or stainless steel. In <strong>diaphragm pumps, the air valves</strong> are positioned between the diaphragms, right at the center of the pump. In this way, air passages and dead volumes are reduced to a minimum. HD Marine also provides its customers with the highest-quality spare part support compatible with Sandpiper.</p><p>A diaphragm pump operates on compressed air. The functional operation of the <strong>valve seats</strong> and <strong>valve balls</strong>, moving back and forth to pump the liquid, is what makes it work. Valve seats and valve balls are critical components for the proper operation of an air-operated double diaphragm pump. <strong>Valve balls and valve seats in Air-Operated Double Diaphragm Pumps</strong> are found in many sectors such as aerospace, environment, energy, automotive, construction, chemicals, ceramics, cosmetics, food and beverage, oil and gas, packaging, steel and metals, and pharmaceuticals.</p><p>As an important part of the general maintenance program, <strong>diaphragms</strong> should be replaced at regular intervals according to the manufacturer's recommendations. A double diaphragm pump uses two flexible diaphragms connected to each other by a shaft moving back and forth, and is also known as a positive displacement pump. The role of the diaphragms is to operate in a way that separates the air on one side from the medium on the other side.</p><p>For questions or problems regarding the <strong>valve seats, valve balls, air valve, diaphragm</strong> or <strong>hardware</strong> of your Air-Operated Double Diaphragm Sandpiper Pump, please contact our professional team members working in HD Marine spare Pump Parts. We would be happy to assist you and reach a solution for your issues with spare parts compatible with Sandpiper-brand products.</p></div> </div>$h$, NULL, $h$Sandpiper® Compatible Spare Parts | HD Marine$h$, $h$HD Marine delivers to its users the highest-quality spare parts compatible with the Sandpiper® brand. It has a complete, wide range of wear parts for…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('aeee2f47-c511-5275-8464-22ccf5b2e087', '53075258-51b5-56e5-9573-f2ed7e9c2540', 'en', $h$Blagdon® Compatible Spare Parts$h$, $h$blagdon-compatible-spare-parts$h$, $h$Blagdon® Compatible Spare Parts$h$, $h$<div> <p>HD Marine serves its customers with spare parts compatible with Blagdon products, in varieties made of materials that change according to the area of use. Diaphragm pumps are used in various applications such as alcohol, chemical treatment, acid / alkali / chemical, paint and pigment, drainage applications, petroleum-derived liquids, ceramic slip, glaze, and oil and solvent transfer. At HD Marine you can find various Blagdon spare part products such as valve balls, valve seats, diaphragms, hardware, rings, gaskets and repair kits.</p> </div><div> <p>In a diaphragm pump's operation on compressed air and in pumping the liquid, the valve seats and valve balls have an important function, moving back and forth. For the pump to operate properly, every part used must be of high quality, robust and made of material suitable for the area in which it will be used. For example, <strong>Valve Ball Neoprene Fit Blagdon Pumps Parts</strong> should be used for non-aggressive liquid applications; <strong>Valve Ball PTFE Fit Blagdon Pumps Parts</strong> when pumping aggressive liquids; <strong>Valve Ball BUNA-N/Nitrile Fit Blagdon Pumps Parts</strong> when pumping petroleum oil-based liquids; <strong>Valve Ball FKM Fit Blagdon Pumps Parts</strong> for liquids such as aggressive acids requiring extreme temperatures; and <strong>Valve Ball EPDM/ Blagdon Pumps Parts</strong> materials for dilute acids requiring extreme cold. Although Blagdon balls products look similar in appearance, their material and color code change according to the area in which they will be used.</p><p>HD Marine also offers material options in Blagdon diaphragm spare part products. The most widely used materials, in varieties such as Neoprene, EPDM, Nitrile and PTFE, reach customers in different sizes and with color codes. Through the HD Marine site you can access the <strong>Blagdon Valve Ball and Blagdon Diaphragm</strong> spare parts you need and review the products. For your questions and requests, you can reach our professional colleagues in the field and obtain information about Blagdon spare part varieties.</p> </div>$h$, NULL, $h$Blagdon® Compatible Spare Parts | HD Marine$h$, $h$HD Marine serves its customers with spare parts compatible with Blagdon products, in varieties made of materials that change according to the area of use…$h$, 'auto') ON CONFLICT DO NOTHING;
